INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Decorator-Pattern nur für UI-Komponenten geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für andere Objekte nutzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Decorator-Pattern?', 3, '[{"text": "Dynamische Funktionserweiterung", "correct": true, "because": "Fügt Verhalten zur Laufzeit hinzu"}, {"text": "Datenmodellierung", "correct": false, "because": "Kein Datenfokus"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Kein Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Decorator-Pattern?', 5, '[{"text": "Komponente", "correct": true, "because": "Basisobjekt"}, {"text": "Decorator", "correct": true, "because": "Erweitert Funktionalität"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Decorator fügt Verhalten hinzu. b) Er ersetzt die Komponente.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Komponente bleibt erhalten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Decorator-Pattern?', 4, '[{"text": "Komponenteninterface", "correct": false, "because": "Grundlage der Erweiterung"}, {"text": "Decorator-Klasse", "correct": false, "because": "Fügt Funktionalität hinzu"}, {"text": "Hardwarezuordnung", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Decorator auch ohne Interface funktioniert?', 2, '[{"text": "Ja", "correct": true, "because": "Mit abstrakter Klasse möglich"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend Interface nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Komponente im Decorator-Pattern?', 3, '[{"text": "Basisobjekt", "correct": true, "because": "Definiert Grundfunktionalität"}, {"text": "Datenquelle", "correct": false, "because": "Kein Datenfokus"}, {"text": "UI-Controller", "correct": false, "because": "Nicht UI-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen das Decorator-Pattern nützlich?', 5, '[{"text": "Dynamische Erweiterung", "correct": true, "because": "Laufzeitflexibilität"}, {"text": "Kompatibilität", "correct": true, "because": "Passt an bestehende Objekte"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Kein Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Decorator erweitert Funktionen. b) Er erstellt neue Objekte von Grund auf. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nutzt bestehende Objekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Decorator-Pattern?', 4, '[{"text": "Komponente", "correct": false, "because": "Basis der Erweiterung"}, {"text": "Decorator", "correct": false, "because": "Fügt Verhalten hinzu"}, {"text": "Netzwerkprotokolle", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Decorator nur für UI-Komponenten?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Objekte erweiterbar"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zum Decorator-Pattern?', 4, '[{"text": "Abstrakte Komponente", "correct": true, "because": "Definiert Interface"}, {"text": "Konkreter Decorator", "correct": true, "because": "Erweitert Funktionalität"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Decorator die Leistung stark senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Overhead meist minimal"}, {"text": "Ja", "correct": false, "because": "Abhängig von Implementierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Decorator-Pattern?', 3, '[{"text": "Flexibilität der Erweiterung", "correct": true, "because": "Kern des Patterns"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Funktion zählt mehr"}, {"text": "Grafische Darstellung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Decorator nutzt Komposition. b) Er ersetzt Vererbung vollständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vererbung ergänzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Decorator-Pattern?', 5, '[{"text": "Laufzeitflexibilität", "correct": true, "because": "Verhalten dynamisch hinzufügen"}, {"text": "Wiederverwendbarkeit", "correct": true, "because": "Komponenten bleiben intakt"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Kein Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Decorator-Pattern unwichtig?', 3, '[{"text": "Komponenteninterface", "correct": false, "because": "Grundlage der Erweiterung"}, {"text": "Decorator-Logik", "correct": false, "because": "Fügt Funktionalität hinzu"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Pattern-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann der Decorator mehrere Erweiterungen stapeln?', 3, '[{"text": "Ja", "correct": true, "because": "Mehrere Decorators kombinierbar"}, {"text": "Nein", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Decorator für statische Erweiterungen geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Dynamisch zur Laufzeit"}, {"text": "Ja", "correct": false, "because": "Nicht statisch gedacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die Basis im Decorator-Pattern?', 4, '[{"text": "Abstrakte Komponente", "correct": true, "because": "Definiert Interface"}, {"text": "Datenfluss", "correct": false, "because": "Anderes Konzept"}, {"text": "UI-Controller", "correct": false, "because": "Nicht UI-spezifisch"}]');
